Вот простой калькулятор с четырьмя операциями и проверкой деления на ноль.

```python
def calculator():
    a = float(input("Первое число: "))
    operator = input("Операция (+, -, *, /): ")
    b = float(input("Второе число: "))

    if operator == "+":
        result = a + b
    elif operator == "-":
        result = a - b
    elif operator == "*":
        result = a * b
    elif operator == "/":
        if b == 0:
            print("Ошибка: делить на ноль нельзя.")
            return
        result = a / b
    else:
        print("Неизвестная операция.")
        return

    print("Результат:", result)

if __name__ == "__main__":
    calculator()
```

